python3 -c "import json,re,subprocess,yaml; t=open('.agent/evidence/104/ci-negative-run.txt').read().splitlines(); assert re.fullmatch(r'gh run view [0-9]+ --json headSha,headBranch,conclusion,jobs',t[0]), t[0]; R=json.loads('\n'.join(t[1:-1])); J=[(k,j.get('name') or k) for k,j in yaml.safe_load(open('.github/workflows/compliance.yml'))['jobs'].items() if any('tools/test_convergent_review.py' in (s.get('run') or '') for s in j['steps'])]; assert len(J)==1, J; jb=[j for j in R['jobs'] if j['name']==J[0][1]]; assert R['conclusion']=='failure' and R['headBranch'].startswith('throwaway/104-') and len(jb)==1 and jb[0]['conclusion']=='failure', (R['conclusion'],R['headBranch'],R['headSha'],jb,t[-1])"
